#include <iomanip>\n#include <iostream>\n#include <memory>\n#include <sstream>\n#include <string>\n#include <vector>\n\nstruct ProofOfProcessReceipt {\n    std::string subsystem;\n    std::string action;\n    std::string event_hash;\n    std::string state;\n};\n\nstruct VehicleState {\n    double position_km = 0.0;\n    double current_speed_kmh = 0.0;\n    double target_speed_kmh = 300.0;\n    double power_kw = 0.0;\n    double thermal_c = 21.0;\n    double drag_coefficient = 0.25;\n    bool track_switch_locked = false;\n    std::string track_switch_authorization;\n    int v2v_signal_strength = 100;\n};\n\nclass IPLSubsystem {\npublic:\n    virtual ~IPLSubsystem() = default;\n    virtual void initialize() = 0;\n    virtual ProofOfProcessReceipt execute(VehicleState& state) = 0;\n    virtual std::string name() const = 0;\n};\n\nstatic std::string deterministic_event_fingerprint(const std::string& subsystem,\n                                                   const std::string& action,\n                                                   const VehicleState& state) {\n    std::ostringstream payload;\n    payload << subsystem << "|" << action << "|"\n            << std::fixed << std::setprecision(6)\n            << state.position_km << "|" << state.current_speed_kmh << "|"\n            << state.power_kw << "|" << state.thermal_c << "|"\n            << state.drag_coefficient << "|" << state.v2v_signal_strength << "|"\n            << (state.track_switch_locked ? "1" : "0");\n    return std::to_string(std::hash<std::string>{}(payload.str()));\n}\n\nclass V2VCommsController final : public IPLSubsystem {\npublic:\n    void initialize() override { std::cout << "[INIT] V2V communications online.\n"; }\n    ProofOfProcessReceipt execute(VehicleState& state) override {\n        state.v2v_signal_strength -= 2;\n        const auto hash = deterministic_event_fingerprint(name(), "receive", state);\n        if (state.v2v_signal_strength < 50) return {name(), "receive", hash, "QUARANTINED"};\n        return {name(), "receive", hash, "VERIFIED_PROCESS"};\n    }\n    std::string name() const override { return "V2V_COMMS"; }\n};\n\nclass MagneticSwitchController final : public IPLSubsystem {\npublic:\n    void initialize() override { std::cout << "[INIT] Magnetic track switching controller online.\n"; }\n    ProofOfProcessReceipt execute(VehicleState& state) override {\n        const std::string command = "SWITCH_TO_TRACK_2";\n        const std::string authorization = "AUTH:" + command;\n        if (!state.track_switch_locked) {\n            state.track_switch_authorization = authorization;\n            return {name(), "authorize", deterministic_event_fingerprint(name(), "authorize", state), "ACTION_REQUIRED"};\n        }\n        if (state.track_switch_authorization == authorization) {\n            return {name(), "verify", deterministic_event_fingerprint(name(), "verify", state), "VERIFIED_PROCESS"};\n        }\n        return {name(), "verify", deterministic_event_fingerprint(name(), "reject", state), "QUARANTINED"};\n    }\n    std::string name() const override { return "MAG_SWITCH"; }\n};\n\nclass AerodynamicsController final : public IPLSubsystem {\npublic:\n    void initialize() override { std::cout << "[INIT] Aerodynamic sensor model online.\n"; }\n    ProofOfProcessReceipt execute(VehicleState& state) override {\n        state.drag_coefficient = 0.25 + (state.current_speed_kmh * state.current_speed_kmh) / 100000.0;\n        const auto hash = deterministic_event_fingerprint(name(), "drag", state);\n        if (state.drag_coefficient > 0.60) return {name(), "evaluate_drag", hash, "QUARANTINED"};\n        return {name(), "evaluate_drag", hash, "VERIFIED_PROCESS"};\n    }\n    std::string name() const override { return "AERODYNAMICS"; }\n};\n\nclass IPLEngine final {\npublic:\n    void register_subsystem(std::unique_ptr<IPLSubsystem> subsystem) { subsystems_.push_back(std::move(subsystem)); }\n    void boot() { for (const auto& subsystem : subsystems_) subsystem->initialize(); }\n    bool run(int cycles) {\n        std::cout << "=== iPL PROCESS-OF-TRUTH SIMULATION ===\n";\n        for (int cycle = 1; cycle <= cycles; ++cycle) {\n            state_.current_speed_kmh = std::min(state_.target_speed_kmh, state_.current_speed_kmh + 20.0);\n            state_.position_km += state_.current_speed_kmh / 3600.0;\n            state_.power_kw = state_.current_speed_kmh < state_.target_speed_kmh ? 250.0 : 50.0;\n            std::cout << "CYCLE " << cycle << " speed=" << state_.current_speed_kmh << " km/h position=" << state_.position_km << " km\n";\n            for (const auto& subsystem : subsystems_) {\n                const ProofOfProcessReceipt receipt = subsystem->execute(state_);\n                std::cout << "  [" << receipt.subsystem << "] " << receipt.action << " -> " << receipt.state << " | " << receipt.event_hash << "\n";\n                if (receipt.state == "QUARANTINED") {\n                    std::cout << "  [iEf] GATE LOCKED. Historical event retained; execution halted.\n";\n                    return false;\n                }\n            }\n        }\n        return true;\n    }\nprivate:\n    VehicleState state_{};\n    std::vector<std::unique_ptr<IPLSubsystem>> subsystems_{};\n};\n\nint main() {\n    IPLEngine engine;\n    engine.register_subsystem(std::make_unique<V2VCommsController>());\n    engine.register_subsystem(std::make_unique<MagneticSwitchController>());\n    engine.register_subsystem(std::make_unique<AerodynamicsController>());\n    engine.boot();\n    return engine.run(15) ? 0 : 2;\n}\n